#![allow(unused)]
use verus::prelude::*;

//
// A helper function that checks whether the four “corner‐arrows”
// form one of the four disconnection patterns.
//
// We require that n and m are strictly positive, and that the
// two input Vec<char>’s have exactly the lengths n and m
// (after casting to usize).  We then ensure that the Boolean
// returned is precisely the same as the disconnection predicate
// on the corner arrows.
//

#[verifier::requires(n > 0)]
#[verifier::requires(m > 0)]
#[verifier::requires(horizontal.len() == n as usize)]
#[verifier::requires(vertical.len()   == m as usize)]
#[verifier::ensures(
    ret == (
        // top-left '>' and left-top 'v'
        (horizontal[0]                    == '>' && vertical[0]                      == 'v')
        ||
        // top-left '<' and right-bottom 'v'
        (horizontal[0]                    == '<' && vertical[m as usize - 1]        == 'v')
        ||
        // bottom-left '>' and left-top '^'
        (horizontal[n as usize - 1]       == '>' && vertical[0]                      == '^')
        ||
        // bottom-left '<' and right-bottom '^'
        (horizontal[n as usize - 1]       == '<' && vertical[m as usize - 1]        == '^')
    )
)]
fn check_disconnected(
    n:       i8,
    m:       i8,
    horizontal: &Vec<char>,
    vertical:   &Vec<char>
) -> bool {
    let n_usize = n as usize;
    let m_usize = m as usize;

    let h_first = horizontal[0];
    let h_last  = horizontal[n_usize - 1];
    let v_first = vertical[0];
    let v_last  = vertical[m_usize - 1];

    (h_first == '>' && v_first == 'v')
     || (h_first == '<' && v_last  == 'v')
     || (h_last  == '>' && v_first == '^')
     || (h_last  == '<' && v_last  == '^')
}

//
// The solve function simply calls check_disconnected and then
// returns either “NO\n” or “YES\n” accordingly.
//
// We carry over the same preconditions, and ensure that the
// returned Vec<char> is exactly the right one.
//

#[verifier::requires(n > 0)]
#[verifier::requires(m > 0)]
#[verifier::requires(horizontal.len() == n as usize)]
#[verifier::requires(vertical.len()   == m as usize)]
#[verifier::ensures(
    if check_disconnected(n, m, &horizontal, &vertical) {
        ret == vec!['N','O','\n']
    } else {
        ret == vec!['Y','E','S','\n']
    }
)]
fn solve(
    n:          i8,
    m:          i8,
    horizontal: Vec<char>,
    vertical:   Vec<char>
) -> Vec<char> {
    if check_disconnected(n, m, &horizontal, &vertical) {
        vec!['N', 'O', '\n']
    } else {
        vec!['Y', 'E', 'S', '\n']
    }
}

fn main() {
    let n = 4;
    let m = 3;
    let horizontal: Vec<char> = vec!['<', '<', '>', '<'];
    let vertical:   Vec<char> = vec!['^', 'v', 'v'];

    let result = solve(n, m, horizontal, vertical);
    let output: String = result.into_iter().collect();
    print!("{}", output);
}